import fs from 'node:fs/promises';
import path from 'node:path';

const DB_PATH = path.join(process.cwd(), 'user-prefs.json');

export interface UserPreferences {
  notifications: boolean;
}

// Ensure db file exists
async function initDb() {
  try {
    await fs.access(DB_PATH);
  } catch {
    await fs.writeFile(DB_PATH, JSON.stringify({ notifications: false }));
  }
}

export async function getPreferences(): Promise<UserPreferences> {
  await initDb();
  const data = await fs.readFile(DB_PATH, 'utf-8');
  return JSON.parse(data);
}

export async function toggleNotifications(): Promise<boolean> {
  await initDb();
  const prefs = await getPreferences();
  const newPrefs = { ...prefs, notifications: !prefs.notifications };
  await fs.writeFile(DB_PATH, JSON.stringify(newPrefs));
  return newPrefs.notifications;
}

