import { getPreferences } from './db';
import { toggleNotificationAction } from './actions';

export default async function Home() {
  const { notifications } = await getPreferences();

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Notification Settings</h1>

      <div style={{ 
        padding: '1rem', 
        border: '1px solid #ccc', 
        borderRadius: '8px',
        maxWidth: '300px'
      }}>
        <p>
          Current Status:{' '}
          <strong style={{ color: notifications ? 'green' : 'red' }}>
            {notifications ? 'ON' : 'OFF'}
          </strong>
        </p>

        <form action={toggleNotificationAction}>
          <button 
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              background: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Toggle Notifications
          </button>
        </form>
      </div>
    </main>
  );
}

